       "source": [
        "%sql\n",
        "CREATE OR REPLACE TABLE billing_data.billing_data_schema.billing_materialized_view (\n",
        "  account_id\tstring,\n",
        "  workspace_id\tstring,\n",
        "  record_id\tstring,\n",
        "  sku_name\tstring,\n",
        "  cloud\tstring,\n",
